/bin/zsh -lc "python3 -c 'import json
with open(\"input.json\") as f:
    d = json.load(f)
selected = {}
for r in d[\"records\"]:
    if r[\"recorded_at\"] <= d[\"cutoff\"] and r[\"release\"] == d[\"release\"] and r[\"environment\"] == d[\"environment\"] and r[\"status\"] in {\"PASS\", \"FAIL\", \"NOT_RUN\", \"UNKNOWN\"}:
        key = (r[\"observed_at\"], r[\"recorded_at\"], r[\"id\"])
        old = selected.get(r[\"gate\"])
        if old is None or key > (old[\"observed_at\"], old[\"recorded_at\"], old[\"id\"]):
            selected[r[\"gate\"]] = r
out = []
unknown_findings = []
findings = 0
for g in sorted(d[\"gates\"], key=lambda g: g[\"id\"]):
    r = selected.get(g[\"id\"])
    status = \"UNKNOWN\" if r is None or d[\"cutoff\"] - r[\"observed_at\"] > d[\"max_age\"] else r[\"status\"]
    out.append({\"id\": g[\"id\"], \"status\": status, \"source\": None if r is None else r[\"id\"]})
    if r is None or r.get(\"findings\") is None:
        unknown_findings.append(g[\"id\"])
    else:
        findings += r[\"findings\"]
statuses = {g[\"id\"]: g[\"status\"] for g in out}
blocked = sorted(g[\"id\"] for g in d[\"gates\"] if any(statuses.get(p, \"UNKNOWN\") "'!= "PASS" for p in g["requires"]))
decision = "BLOCKED" if "FAIL" in statuses.values() else "INCOMPLETE" if blocked or any(s in {"UNKNOWN", "NOT_RUN"} for s in statuses.values()) else "READY"
print(json.dumps({"gates":out, "decision":decision, "blocked_dependencies":blocked, "observed_findings":findings, "unknown_finding_gates":unknown_findings}, separators=(",", ":")))'"'"

